// Renders docs/assets/ (manifest.json, README.md and one page per category) from the manifest. Pure: same manifest in, same text out.
import { CATEGORIES, type AssetEntry } from './manifest';
import type { SoundEntry } from './sounds';

const HEADER =
	'Generated by `npm run assets:catalog` from the game registries and `public/pixel/`. Do not edit by hand: rename an asset in `scripts/assets/names.json`.';

const STATUS_TEXT: Record<AssetEntry['status'], string> = {
	used: 'in the game now',
	planned: 'its item, monster or resource exists but is disabled (not in the game yet)',
	retired: 'item no longer drops or sells; saves that already hold it keep working',
	unused: 'registered art that nothing uses: an icon with no item, or an icon no code references (safe to delete once checked)',
	placeholder: 'stand-in silhouette until real art arrives',
	spare: 'generated art nobody needs yet (`_name.png`)',
	reuse: 'raw pack art, not wired; copy only what you use',
};

/** Path from docs/assets/*.md to a file under public/ (URL-encoded: pack files have spaces and brackets) */
const rel = (src: string) => '../../public' + src.split('/').map(encodeURIComponent).join('/').replace(/%2F/g, '/');
const img = (e: AssetEntry) => `<img src="${rel(e.src)}" width="${Math.min(Math.max(e.size[0], 24) * 2, 96)}" alt="${e.name}">`;

export const renderManifestJson = (m: AssetEntry[]): string => JSON.stringify(m, null, '\t') + '\n';

export const renderCategory = (id: string, m: AssetEntry[]): string => {
	const cat = CATEGORIES.find((c) => c.id === id)!;
	const rows = m.filter((e) => e.category === id);
	const out: string[] = [`# ${cat.title}`, '', HEADER, '', cat.blurb, '', `${rows.length} assets. Refer to an asset by its **name**.`, ''];
	const subs = [...new Set(rows.map((e) => e.subcategory))];
	for (const sub of subs) {
		out.push(`## ${sub}`, '', '| Name | Picture | Size | Status | Used by | Source file |', '| --- | --- | --- | --- | --- | --- |');
		for (const e of rows.filter((r) => r.subcategory === sub)) {
			const variants = e.variants ? ` (variants: ${Object.keys(e.variants).join(', ')})` : '';
			out.push(`| \`${e.name}\` | ${img(e)} | ${e.size.join('x')} | ${e.status} | ${e.usedBy.join(', ')} | \`${e.src.slice(1)}\`${variants} |`);
		}
		out.push('');
	}
	return out.join('\n');
};

export const renderIndex = (m: AssetEntry[]): string => {
	const out: string[] = ['# Asset library', '', HEADER, ''];
	out.push(
		'One name per picture, grouped by what it is. Biomes, terrain atlases and ground textures are not listed. Browse it visually with `npm run storybook` (stories under `stories/assets/`).',
		'',
		'## How to use it with an agent',
		'',
		'- **Use an asset:** "use `building_village_blacksmith_house` for the Blacksmith". The agent finds the file in `manifest.json` (`src`), copies it into the game folder and registers it (`src/config/pixelIcons.ts` or `src/config/itemIcons/`; rules in `art_style_reference/README.md`).',
		'- **Delete an asset:** "delete `potion_pack_07`". Only `reuse` and `spare` assets are safe to delete outright; for a `used`, `planned` or `retired` asset the agent first switches the catalog entry to another picture (never delete a wired file before its replacement is wired).',
		'- **Rename:** add `"<src as in manifest.json>": "new_name"` to `scripts/assets/names.json` and run `npm run assets:catalog`.',
		'- **Map details:** pack objects come in up to four renderings of the same object (`none`, `shadow`, `texture`, `texture-dark`); the page lists them as `variants`. Pick the one that sits on your ground.',
		'',
		'## Status',
		'',
		...Object.entries(STATUS_TEXT).map(([k, v]) => `- \`${k}\`: ${v}`),
		'',
		'## Categories',
		'',
		'| Category | Assets | In the game | Reuse pool |',
		'| --- | --- | --- | --- |',
	);
	for (const c of CATEGORIES) {
		const rows = m.filter((e) => e.category === c.id);
		out.push(
			`| [${c.title}](${c.id}.md) | ${rows.length} | ${rows.filter((e) => e.status === 'used').length} | ${rows.filter((e) => e.status === 'reuse').length} |`,
		);
	}
	out.push('', "[Sounds](sounds.md): UI and game sound effects (the game's own plus the CC0 Kenney packs in `public/sfx/`), with lengths.", '');
	return out.join('\n');
};

export const renderSounds = (sounds: SoundEntry[]): string => {
	const out = [
		'# Sounds',
		'',
		HEADER,
		'',
		`${sounds.length} sounds. Play them in Storybook (\`npm run storybook\`, Sounds) and refer to one by its **name**.`,
		'',
	];
	for (const group of [...new Set(sounds.map((e) => e.group))]) {
		out.push(`## ${group}`, '', '| Name | Length | Status | Use for | Source file |', '| --- | --- | --- | --- | --- |');
		for (const e of sounds.filter((x) => x.group === group))
			out.push(
				`| \`${e.name}\` | ${e.durationMs ? `${(e.durationMs / 1000).toFixed(2)} s` : ''} | ${e.status} | ${[...e.usedBy, e.use].filter(Boolean).join(', ')} | \`${e.src.slice(1)}\` |`,
			);
		out.push('');
	}
	return out.join('\n');
};

/** file name (relative to docs/assets) -> text */
export const renderAll = (m: AssetEntry[], sounds: SoundEntry[]): Record<string, string> => ({
	'sounds.json': JSON.stringify(sounds, null, '\t') + '\n',
	'sounds.md': renderSounds(sounds),
	'manifest.json': renderManifestJson(m),
	'README.md': renderIndex(m),
	...Object.fromEntries(CATEGORIES.map((c) => [`${c.id}.md`, renderCategory(c.id, m)])),
});
